import { Component, OnInit } from '@angular/core';
import { SalesService } from 'src/app/services/sales.service';
import { Sale } from 'src/app/models/sale.model';

@Component({
  selector: 'app-sales',
  templateUrl: './sales.component.html',
  styleUrls: ['./sales.component.css'],
})
export class SalesComponent implements OnInit {
  sales: Sale[] = [];
  isLoading = false;

  constructor(private salesService: SalesService) {}

  ngOnInit(): void {
    this.getSales();
  }

  getSales(): void {
    this.isLoading = true;
    this.salesService.getAllSales().subscribe({
      next: (data) => {
        this.sales = data;
        this.isLoading = false;
      },
      error: (err) => {
        console.error('❌ Error fetching sales:', err);
        this.isLoading = false;
      },
    });
  }

  refreshData(): void {
    this.getSales();
  }

  viewSaleDetails(sale: Sale): void {
    console.log('Viewing sale details:', sale);
    // You can customize this action
    alert(`Viewing sale #${sale.id}: ${sale.itemName}`);
  }

  editSale(sale: Sale): void {
    console.log('Editing sale:', sale);
    // You can customize this action
    alert(`Editing sale #${sale.id}: ${sale.itemName}`);
  }
}
